SELECT FIRST_VALUE(x0.v142015) OVER (ORDER BY x0.v142015 RANGE BETWEEN INTERVAL (NULL) HOUR PRECEDING AND INTERVAL '1' HOUR PRECEDING), SUM(x0.v142015) OVER (ORDER BY x0.v142015 DESC, x0.v142015, x0.v142015 RANGE BETWEEN INTERVAL '2' DAY PRECEDING AND CURRENT ROW) FROM v142014 AS x0 WINDOW x1 AS (PARTITION BY x0.v142015 ORDER BY -x0.v142015)